160	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of
161	     * owners already present in the same city, zero-padded to four digits
162	     * (e.g. {@code 'LONDON-0007'}). Cities are matched ignoring letter case.
163	     *
164	     * @param city the city of the owner about to be created
165	     * @return the formatted customer code
166	     */
167	    private String nextCustomerCode(String city) {
168	        long ownersInCity = this.clinicService.findAllOwners().stream()
169	            .filter(existing -> existing.getCity() != null
170	                && existing.getCity().equalsIgnoreCase(city))
171	            .count();
